    ('91baee7f-02c0-4fd5-8d5d-b6e365a80ed3', 'c4717e10-d9ce-4597-83bf-80643640a752', 'abd1710a-33da-4b35-8f05-d7fcc60027e7', false, '{"selectedOptions":[3]}', 57, 'assessment', now() - interval '790286 seconds', null, 'missing'),
    ('868292c6-991b-492b-8b47-4373ba97d7a5', 'c4717e10-d9ce-4597-83bf-80643640a752', '82e82fd1-c814-4f98-8770-3eb0cc3857c7', true, '{"selectedOptions":[0]}', 32, 'assessment', now() - interval '790211 seconds', null, 'missing'),
    ('40fe1ec3-addb-41d6-8687-2026935339ba', 'c4717e10-d9ce-4597-83bf-80643640a752', '3d7bc7a8-57f3-4937-817c-aa972998d375', true, '{"selectedOptions":[3]}', 85, 'assessment', now() - interval '790136 seconds', 'because we see an object when light from a source is reflected by the object into our eyes; eyes receive light, they do not send it out', 'sound'),
    ('39323e10-ebbb-4244-8b87-3c430218eb46', 'c4717e10-d9ce-4597-83bf-80643640a752', '57f4bac0-8d13-498d-8567-afbab828b3f4', true, '{"selectedOptions":[2]}', 73, 'assessment', now() - interval '790061 seconds', 'because by Ohm''s law I = V/R; R is fixed for the conductor, so doubling V doubles I', 'sound'),
    ('b3ad3115-e2e1-4fd6-8834-efc1137587ef', 'c4717e10-d9ce-4597-83bf-80643640a752', 'b10c49e6-b453-49d3-87a0-3f7385c2943a', false, '{"selectedOptions":[3]}', 116, 'assessment', now() - interval '789986 seconds', null, 'missing'),
    ('3098e343-cf55-4fcb-8f6c-67faf194ec4c', 'c4717e10-d9ce-4597-83bf-80643640a752', '5cafd5fc-1b47-4343-826b-fd378f3546e4', true, '{"selectedOptions":[1]}', 60, 'assessment', now() - interval '789911 seconds', 'because a planet is seen as a collection of point sources; their variations cancel out on average, so it does not twinkle', 'sound'),
    ('83011580-3928-4642-84bd-60a286538d1c', 'c4717e10-d9ce-4597-83bf-80643640a752', '1f363bb6-9fdc-4436-83c4-ca9c632688f7', false, '{"selectedOptions":[2]}', 37, 'assessment', now() - interval '789836 seconds', 'not sure', 'missing'),
    ('d2830ffc-ccd6-480e-81ed-3bafad6470e5', 'c4717e10-d9ce-4597-83bf-80643640a752', '43770002-8762-4881-8ec9-d41ad7e134dd', false, '{"selectedOptions":[1]}', 80, 'assessment', now() - interval '789761 seconds', null, 'missing'),
    ('b6a27047-0b6e-4fda-8aeb-9e438562f492', 'c4717e10-d9ce-4597-83bf-80643640a752', 'dd5c1682-0093-477a-8bd8-ed8cafd851a7', true, '{"selectedOptions":[0]}', 100, 'assessment', now() - interval '789686 seconds', 'because paper gives diffuse reflection: its tiny surface bumps face many directions, so reflected rays scatter, though each one obeys the laws of reflection', 'sound'),
    ('178e256a-373c-40a9-8f2f-acc56f7d2c15', 'c4717e10-d9ce-4597-83bf-80643640a752', '0f25728e-daad-4fe2-8fe0-c906087dd055', true, '{"selectedOptions":[2]}', 42, 'assessment', now() - interval '789611 seconds', 'because with the object between P and F, a concave mirror forms a virtual, erect, magnified image behind the mirror, as in a shaving mirror', 'sound'),
    ('b5872a58-7c6c-4a79-89ae-e14e38f60af2', 'c4717e10-d9ce-4597-83bf-80643640a752', '0e26472d-1d73-4655-8d35-0755bcfe4c73', true, '{"selectedOptions":[2]}', 28, 'assessment', now() - interval '789536 seconds', null, 'missing'),
    ('10c382e4-7094-4ce6-83bd-d77a323df701', 'c4717e10-d9ce-4597-83bf-80643640a752', 'd222eaba-ac8f-401b-8d76-dd0437f502b8', false, '{"selectedOptions":[3]}', 74, 'assessment', now() - interval '789461 seconds', null, 'missing'),
    ('80e30b93-09ee-4672-8057-7b9541ff7233', 'c4717e10-d9ce-4597-83bf-80643640a752', 'e8c0f160-32d0-4f92-809c-bf185454600f', true, '{"selectedOptions":[0]}', 78, 'practice', now() - interval '703171 seconds', 'because by convention, outside a magnet the field lines emerge from the north pole and enter the south pole', 'sound'),
    ('c10c12ad-4ea2-4f4b-860c-0a8598adc775', 'c4717e10-d9ce-4597-83bf-80643640a752', '8b85080d-82ba-4b9d-8fcc-95aabf40a3a4', true, '{"selectedOptions":[0]}', 79, 'practice', now() - interval '700972 seconds', 'because the object is placed to the left, and distances measured against the direction of incident light are negative, so u is always negative', 'sound'),
    ('1bf81880-be55-4a73-8437-537f5d56eac1', 'c4717e10-d9ce-4597-83bf-80643640a752', 'f6eedc74-f4d2-42a3-82ff-f980229ee5bf', true, '{"selectedOptions":[1]}', 41, 'practice', now() - interval '698206 seconds', 'because the image is 2 m behind the mirror, so it is 2 m + 2 m = 4 m from you', 'sound'),
    ('cdb60f00-5554-4c79-8822-d79da3e1a417', 'c4717e10-d9ce-4597-83bf-80643640a752', '29bd2c12-f686-4c12-8517-dd85d63d704e', false, '{"selectedOptions":[1]}', 83, 'practice', now() - interval '694357 seconds', null, 'missing'),
    ('be011fcb-9f5f-4de2-8766-06e8fe3814e1', 'c4717e10-d9ce-4597-83bf-80643640a752', 'de054d88-7c0a-4f0b-88dd-1526ae8bf1b4', true, '{"selectedOptions":[2]}', 44, 'practice', now() - interval '692381 seconds', 'because for a spherical mirror f = R/2, so f = 30/2 = 15 cm', 'sound'),
    ('9f0905a9-8bae-4ed2-8e6e-ae9a352250b5', 'c4717e10-d9ce-4597-83bf-80643640a752', 'c92d2ddb-c033-4d46-8273-b5efedcaba04', false, '{"selectedOptions":[1]}', 112, 'practice', now() - interval '688567 seconds', 'not sure', 'missing'),
    ('cdc468c3-c9f3-46a1-89be-209c142cb3d5', 'c4717e10-d9ce-4597-83bf-80643640a752', 'c0e4c20b-6ea5-46a7-84dd-0642a338f55b', true, '{"selectedOptions":[1]}', 65, 'practice', now() - interval '686227 seconds', 'because light slows down in glass, an optically denser medium, so it bends towards the normal', 'sound'),
    ('1bdfbbff-5da1-4976-836c-7d31c323e288', 'c4717e10-d9ce-4597-83bf-80643640a752', '7a38d880-3b17-4284-89e5-9520930e929b', true, '{"selectedOptions":[0]}', 88, 'practice', now() - interval '683226 seconds', null, 'missing'),
    ('31770136-088a-4b42-8906-c299078c7146', 'c4717e10-d9ce-4597-83bf-80643640a752', '29bd2c12-f686-4c12-8517-dd85d63d704e', false, '{"selectedOptions":[3]}', 50, 'practice', now() - interval '680935 seconds', null, 'missing'),
    ('5d4246e8-5699-4b7f-87ba-80bf2536f0bd', 'c4717e10-d9ce-4597-83bf-80643640a752', '578a717f-8e50-4460-8b35-39ee0c183e81', true, '{"selectedOptions":[2]}', 82, 'practice', now() - interval '678265 seconds', 'because every part of the lens forms the whole image, so the uncovered half still forms a complete image, only with less light', 'sound'),
    ('456d41ab-8b16-4c41-866d-674d104a24a7', 'c4717e10-d9ce-4597-83bf-80643640a752', '1a452450-364e-43f3-8a35-9df87a8b4520', true, '{"selectedOptions":[1]}', 67, 'practice', now() - interval '675002 seconds', 'because p = 1/f with f in metres: P = 1/0.25 m = +4 D, positive because the lens is convex', 'sound'),
    ('0d83b5c0-0c46-468b-8688-8d24d1da7b15', 'c4717e10-d9ce-4597-83bf-80643640a752', '6fbd16c9-89e2-4be5-84b1-51d401722a0b', true, '{"selectedOptions":[2]}', 66, 'practice', now() - interval '671720 seconds', 'because with u = −30 cm and f = −15 cm, 1/v = 1/f − 1/u = −1/15 + 1/30 = −1/30, so v = −30 cm: the image is 30 cm in front, at C', 'sound'),
    ('20700b1e-93bb-4c46-82ae-1f80abab98e2', 'c4717e10-d9ce-4597-83bf-80643640a752', '8c374e00-7af4-43d1-8c8f-15abb4373727', false, '{"selectedOptions":[0]}', 74, 'practice', now() - interval '668949 seconds', 'not sure', 'missing'),
    ('bf34e590-b3e8-401a-8580-ad9711570e3d', 'c4717e10-d9ce-4597-83bf-80643640a752', '52f249a8-2007-4451-87ca-cf5d489925c4', true, '{"selectedOptions":[2]}', 42, 'practice', now() - interval '666370 seconds', null, 'missing'),
    ('10459e32-fd82-4919-87fb-0615d0fa7f81', 'c4717e10-d9ce-4597-83bf-80643640a752', 'e8c0f160-32d0-4f92-809c-bf185454600f', true, '{"selectedOptions":[0]}', 57, 'practice', now() - interval '662817 seconds', 'because by convention, outside a magnet the field lines emerge from the north pole and enter the south pole', 'sound'),
    ('eb7ffcd6-25ed-445e-80e7-e1f7965e4a40', 'c4717e10-d9ce-4597-83bf-80643640a752', '8c6a881e-5dac-43a6-8c89-95f6d21fa345', true, '{"selectedOptions":[1]}', 25, 'practice', now() - interval '660672 seconds', 'because white light is a mixture of colours; each colour has a slightly different refractive index in glass, so they separate (dispersion)', 'sound'),
    ('6b6a403f-ed9b-4142-899c-ad47dbe792ac', 'c4717e10-d9ce-4597-83bf-80643640a752', '9ead298c-2fd0-4e8f-8e03-c76afcce7178', false, '{"selectedOptions":[0]}', 71, 'practice', now() - interval '657108 seconds', null, 'missing'),
    ('a7fae6dd-cf83-4889-8834-051f97a8f15b', 'c4717e10-d9ce-4597-83bf-80643640a752', 'eb4f69d2-0789-422c-8ce4-f41abd669bba', false, '{"selectedOptions":[0]}', 104, 'practice', now() - interval '654645 seconds', null, 'missing'),
    ('88b6603e-aa71-43f4-869b-1b934038eca4', 'c4717e10-d9ce-4597-83bf-80643640a752', '7aa6c9b8-2cc6-40a5-879d-ea99f7618237', true, '{"selectedOptions":[1]}', 60, 'practice', now() - interval '652153 seconds', null, 'missing'),
    ('0a4eb7d6-c170-4a86-8cdd-fbc2c7b67e88', 'c4717e10-d9ce-4597-83bf-80643640a752', 'de06817c-4d9f-400d-8dec-1467419f33db', false, '{"selectedOptions":[2]}', 52, 'practice', now() - interval '648709 seconds', 'not sure', 'missing'),
    ('8fda87c8-1cd0-4b15-8513-5ca9e267ac02', 'c4717e10-d9ce-4597-83bf-80643640a752', '2879a720-6d0b-471c-8b09-15a59122afbe', true, '{"selectedOptions":[3]}', 116, 'practice', now() - interval '645502 seconds', 'because for near objects the ciliary muscles contract, making the lens thicker and its focal length shorter; this is accommodation', 'sound'),
    ('65aa03fd-b7e1-4372-8a4c-2f7b4ab29d68', 'c4717e10-d9ce-4597-83bf-80643640a752', '7aa6c9b8-2cc6-40a5-879d-ea99f7618237', false, '{"selectedOptions":[2]}', 63, 'practice', now() - interval '642812 seconds', 'not sure', 'missing'),
    ('ece40cad-94fd-4a5f-8e87-cf3f5c2b4ce2', 'c4717e10-d9ce-4597-83bf-80643640a752', 'd6391095-1109-4398-8d8c-0bf3add7cc3d', true, '{"selectedOptions":[0]}', 115, 'practice', now() - interval '639721 seconds', 'because the eye''s focal length cannot be reduced below a limit, so objects closer than the near point (about 25 cm) cannot be focused on the retina', 'sound'),
