    ('480a77f7-fa4c-4f9d-87b5-29ce5010dbdf', 'b450531f-2ff9-4c95-8934-dbc94111b3dd', 'dd5c1682-0093-477a-8bd8-ed8cafd851a7', true, '{"selectedOptions":[0]}', 65, 'assessment', now() - interval '805048 seconds', 'because paper gives diffuse reflection: its tiny surface bumps face many directions, so reflected rays scatter, though each one obeys the laws of reflection', 'sound'),
    ('ec2d0cf5-07fa-4fea-83ac-1a4c373dcbc0', 'b450531f-2ff9-4c95-8934-dbc94111b3dd', '7aa6c9b8-2cc6-40a5-879d-ea99f7618237', true, '{"selectedOptions":[1]}', 116, 'assessment', now() - interval '804973 seconds', 'because the tangent to a field line gives the field direction; a crossing would give two directions at one point', 'sound'),
    ('6472eeb8-d381-4b72-8bcf-bb1c2e032e8e', 'b450531f-2ff9-4c95-8934-dbc94111b3dd', 'cfe47243-9ba2-44b4-8749-5d5f805ea814', false, '{"selectedOptions":[0]}', 34, 'assessment', now() - interval '804898 seconds', 'kWh tells you how powerful an appliance is.', 'flawed'),
