    ('e2b719d1-4922-4396-80a4-762b41ccc9af', '7d4b9ad8-6085-4a1f-8b0b-94b47ceced3e', '0e26472d-1d73-4655-8d35-0755bcfe4c73', true, '{"selectedOptions":[2]}', 75, 'assessment', now() - interval '701172 seconds', null, 'missing'),
